timeSeriesQuery.prometheusQuery:
label_replace(
  avg by (project_id, database_id) (
    avg_over_time(
      cloudsql_googleapis_com:database_replication_replica_lag{monitored_resource="cloudsql_database"}[${__interval}]
    )
    and on(project_id, database_id)
    (
      cloudsql_googleapis_com:database_replication_state{monitored_resource="cloudsql_database"}
    )
  ),
  "database_id", "$1", "database_id", ".*:(.*)"
)

